class Solution {
    static class Transaction{
        String raw,name,city;
        int time,amount;
        Transaction(String raw){
            this.raw=raw;
            String[] parts=raw.split(",");
            name=parts[0];
            time=Integer.parseInt(parts[1]);
            amount=Integer.parseInt(parts[2]);
            city=parts[3];
        }
    }
    public List<String> invalidTransactions(String[] input){
        int n=input.length;
        Transaction[] transactions=new Transaction[n];
        boolean[] invalid=new boolean[n];
        for(int i=0;i<n;i++){
            transactions[i]=new Transaction(input[i]);
            invalid[i]=transactions[i].amount>1000;
        }
        for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){
            Transaction a=transactions[i],b=transactions[j];
            if(a.name.equals(b.name)&&!a.city.equals(b.city)&&Math.abs(a.time-b.time)<=60)invalid[i]=invalid[j]=true;
        }
        List<String> answer=new ArrayList<>();
        for(int i=0;i<n;i++)if(invalid[i])answer.add(input[i]);
        return answer;
    }
}

code.kotlin:
class Solution {
    private data class Transaction(val raw:String,val name:String,val time:Int,val amount:Int,val city:String);
    fun invalidTransactions(input:Array<String>):List<String>{
        val transactions=input.map{
            raw->val parts=raw.split(',');
            Transaction(raw,parts[0],parts[1].toInt(),parts[2].toInt(),parts[3])
        };
        val invalid=BooleanArray(input.size){
            transactions[it].amount>1000
        };
        for(i in transactions.indices)for(j in i+1 until transactions.size){
            val a=transactions[i];
            val b=transactions[j];
            if(a.name==b.name&&a.city!=b.city&&kotlin.math.abs(a.time-b.time)<=60){
                invalid[i]=true;
                invalid[j]=true
            }
        };
        return input.indices.filter{
            invalid[it]
        }.map{
            input[it]
        }
    }
}

